            gtpLayer->getMessageTypeAsString();
            gtpLayer->isGTPUMessage();
            gtpLayer->isGTPCMessage();
            auto ext = gtpLayer->getNextExtension();
            ext.getExtensionType();
            ext.getContent();
            ext.getContentLength();
            ext.getNextExtension();
        }
